    "program": ";; A dashboard workflow: independent lookups run concurrently, batches are\n;; bounded, flaky calls are retried, slow ones are raced or timed out, and\n;; background work is forked and joined while a Ref counts progress.\n(type Profile {:id String :name String})\n(type Activity {:id String :events Int})\n(type Dashboard {:profile Profile :activity Activity :score Int})\n(error Unavailable {:service String})\n(service\n  Profiles\n  (: fetch (-> String (Effect Profile [Unavailable] [])))\n  (: cached (-> String (Effect Profile [Unavailable] []))))\n(service Activities (: fetch (-> String (Effect Activity [Unavailable] []))))\n(service Metrics (: track (-> String Int (Effect Unit))))\n(:\n  dashboard\n  (-> String (Effect Dashboard [Unavailable] [Profiles.fetch Activities.fetch])))\n(define\n  dashboard\n  [id]\n  (do!\n    [\n      parts\n      (all\n        {\n          :profile\n            (retry\n              (Profiles.fetch id)\n              :times\n              2\n              :schedule\n              (exponential (millis 1)))\n          :activity (Activities.fetch id)}\n        :concurrency\n        :unbounded)]\n    (succeed\n      {\n        :profile (get parts :profile)\n        :activity (get parts :activity)\n        :score (* 10 (get (get parts :activity) :events))})))\n(:\n  dashboards\n  (->\n    (List String)\n    (Effect (List Dashboard) [Unavailable] [Profiles.fetch Activities.fetch])))\n(define dashboards [ids] (for-each ids (fn [id] (dashboard id)) :concurrency 2))\n(: fastest-profile (-> String (Effect Profile [Unavailable] [Profiles])))\n(define fastest-profile [id] (race (Profiles.fetch id) (Profiles.cached id)))\n(:\n  dashboard-within\n  (->\n    String\n    Int\n    (Effect (Option Dashboard) [Unavailable] [Profiles.fetch Activities.fetch])))\n(define\n  dashboard-within\n  [id millis]\n  (catch\n    (do! [board (timeout (dashboard id) millis)] (succeed (Some board)))\n    (TimeoutError _)\n    (succeed None)))\n(:\n  compare-activity\n  (->\n    String\n    String\n    (Effect (Tuple Activity Activity) [Unavailable] [Activities])))\n(define\n  compare-activity\n  [left right]\n  (all [(Activities.fetch left) (Activities.fetch right)] :concurrency 2))\n(: track-all (-> (List String) (Effect Int [] [Metrics])))\n(define\n  track-all\n  [names]\n  (do!\n    [\n      counter\n      (ref-make 0)\n      worker\n      (fork\n        (for-each\n          names\n          (fn\n            [name]\n            (do!\n              [_ (sleep (millis 1)) _ (ref-update counter (fn [n] (+ n 1)))]\n              (Metrics.track name 1)))\n          :concurrency :unbounded))\n      _\n      (join worker)\n      total\n      (ref-get counter)]\n    (succeed total)))\n(: heartbeat (-> Int (Effect Unit [] [Metrics.track])))\n(define\n  heartbeat\n  [beats]\n  (repeat (Metrics.track \"heartbeat\" 1) :times beats :schedule (spaced 1)))\n"
