    "program": ";; Resource safety: connections are acquired with acquire-release and closed\n;; in reverse order when their scope ends, whether the work succeeds or\n;; fails. A layer holds a connection for its whole lifetime.\n(type Connection {:id String})\n(type Row {:region String :amount Int})\n(error QueryFailed {:query String})\n(service\n  Pool\n  (: open (-> String (Effect Connection)))\n  (: close (-> Connection (Effect Unit)))\n  (: query (-> Connection String (Effect (List Row) [QueryFailed] []))))\n(service Audit (: record (-> String (Effect Unit))))\n(service ReportStore (: save (-> String Int (Effect Unit [QueryFailed] []))))\n(: connection (-> String (Effect Connection [] [Pool Scope])))\n(define\n  connection\n  [name]\n  (acquire-release (Pool.open name) (fn [opened] (Pool.close opened))))\n(: add-row (-> (Map String Int) Row (Map String Int)))\n(define\n  add-row\n  [totals row]\n  (assoc\n    totals\n    (get row :region)\n    (+ (get-or-else (get totals (get row :region)) 0) (get row :amount))))\n(:\n  regional-totals\n  (-> String (Effect (Map String Int) [QueryFailed] [Pool Audit])))\n(define\n  regional-totals\n  [sql]\n  (scoped\n    (do!\n      [\n        _\n        (add-finalizer (Audit.record \"report finished\"))\n        primary\n        (connection \"primary\")\n        replica\n        (connection \"replica\")\n        rows\n        (Pool.query primary sql)\n        _\n        (Audit.record\n          (str \"read \" (count rows) \" rows; replica \" (get replica :id) \" idle\"))]\n      (succeed (reduce add-row (: {} (Map String Int)) rows)))))\n(: publish (-> String (Effect Int [QueryFailed] [Pool Audit ReportStore])))\n(define\n  publish\n  [sql]\n  (ensuring\n    (do!\n      [\n        totals\n        (regional-totals sql)\n        :let\n        [grand (sum (vals totals))]\n        _\n        (ReportStore.save \"grand-total\" grand)]\n      (succeed grand))\n    (Audit.record \"publish attempted\")))\n(layer\n  ReportStoreLive\n  :provides\n  ReportStore\n  :setup\n  [store (connection \"reports\")]\n  (define\n    save\n    [name total]\n    (do! [_ (Pool.query store (str \"insert \" name \" \" total))] (succeed nil))))\n"
