    "program": ";; Streams: lazy pipelines built from collections and ranges, transformed\n;; with pure and effectful steps, and run by collecting, folding, or\n;; consuming each element. Stream types carry the errors and requirements\n;; of the effects folded into them.\n(type Reading {:sensor String :celsius Float})\n(error SensorOffline {:sensor String})\n(service Sensors (: read (-> String (Effect Reading [SensorOffline] []))))\n(service Sink (: write (-> String (Effect Unit))))\n(: celsius-values (-> (List Reading) (Stream Float [] [])))\n(define\n  celsius-values\n  [readings]\n  (stream-map (stream-of readings) (fn [reading] (get reading :celsius))))\n(:\n  hot-readings\n  (->\n    (List String)\n    Float\n    (Effect (List Reading) [SensorOffline] [Sensors.read])))\n(define\n  hot-readings\n  [sensors threshold]\n  (stream-run-collect\n    (stream-filter\n      (stream-map-effect\n        (stream-of sensors)\n        (fn [sensor] (Sensors.read sensor))\n        2)\n      (fn [reading] (> (get reading :celsius) threshold)))))\n(: sum-of-squares (-> Int (Effect Int)))\n(define\n  sum-of-squares\n  [n]\n  (stream-run-fold\n    (stream-map (stream-range 1 n) (fn [i] (* i i)))\n    0\n    (fn [total square] (+ total square))))\n(:\n  export-first\n  (-> (List String) Int (Effect Unit [SensorOffline] [Sensors Sink])))\n(define\n  export-first\n  [sensors limit]\n  (stream-run-for-each\n    (stream-take\n      (stream-map-effect\n        (stream-of sensors)\n        (fn [sensor] (Sensors.read sensor)))\n      limit)\n    (fn\n      [reading]\n      (Sink.write (str (get reading :sensor) \"=\" (get reading :celsius))))))\n(: average (-> (List Reading) (Effect Float)))\n(define\n  average\n  [readings]\n  (do!\n    [\n      total\n      (stream-run-fold\n        (celsius-values readings)\n        (: 0 Float)\n        (fn [sum value] (+ sum value)))]\n    (succeed (if (empty? readings) 0 (/ total (count readings))))))\n"
